card_mod.style:
ha-card {
 --card-padding: 8px 12px !important;
 --weather-forecast-card-current-conditions-icon-size: 40px !important;
 --weather-forecast-card-forecast-conditions-icon-size: 26px !important;
}
.wfc-container, .wfc-current-weather { gap: 4px !important; }
.wfc-current-attributes {
 flex-direction: row !important;
 flex-wrap: wrap !important;
 justify-content: center !important;
 gap: 4px 24px !important;
}
.wfc-current-attribute { flex: 0 1 auto !important; gap: 5px !important; font-size: 12px !important; }
.wfc-current-attribute-icon { padding-left: 0 !important; --mdc-icon-size: 16px !important; }
.wfc-current-attribute-name { padding-left: 0 !important; flex: 0 1 auto !important; }
.wfc-current-attribute-value { font-weight: 500 !important; }
.wfc-forecast-chart { height: 112px !important; }

.wfc-forecast-slot { gap: 2px !important; }

.wfc-current-attribute:nth-child(1) .wfc-current-attribute-value { font-size:0 !important; }
.wfc-current-attribute:nth-child(1) .wfc-current-attribute-value::after { font-size:12px; content: '{{ ('%.1f' | format(states('sensor.molnet_openuv_aktuellt_uv_index') | float)) | replace('.', ',') if is_number(states('sensor.molnet_openuv_aktuellt_uv_index')) else '—' }} UVI'; }

.wfc-current-attribute:nth-child(2) .wfc-current-attribute-value { font-size:0 !important; }
.wfc-current-attribute:nth-child(2) .wfc-current-attribute-value::after { font-size:12px; content: '{{ ('%.1f' | format(states('sensor.utomhus_ljussensor_uv_index') | float)) | replace('.', ',') if is_number(states('sensor.utomhus_ljussensor_uv_index')) else '—' }} UVI'; }

.wfc-current-attribute:nth-child(3) .wfc-current-attribute-value { font-size:0 !important; }
.wfc-current-attribute:nth-child(3) .wfc-current-attribute-value::after { font-size:12px; content: '{{ ('%.1f' | format(states('sensor.molnet_openuv_max_uv_index') | float)) | replace('.', ',') if is_number(states('sensor.molnet_openuv_max_uv_index')) else '—' }} UVI'; }


/* UV values occupy the top of the card, not the subheading line. */
.wfc-current-weather { position:relative !important; }
wfc-current-weather-attributes { display:contents !important; }
.wfc-current-attributes {
 position:absolute !important; top:0 !important; bottom:auto !important;
 left:0 !important; right:0 !important; width:auto !important;
 margin:0 !important; gap:4px 12px !important;
}
.wfc-current-conditions { padding-top:24px !important; box-sizing:border-box; }
@container wfc-container (min-width:900px) {
 .wfc-current-conditions { padding-top:0 !important; }
 .wfc-current-attributes { left:24% !important; right:24% !important; flex-wrap:nowrap !important; }
 .wfc-forecast-chart { height:136px !important; }
}

events.mounted:
EVAL:(chart) => {
 const w=chart.w, g=w?.globals;
 if(!g||!Number.isFinite(g.minX)||!Number.isFinite(g.maxX)||g.maxX<=g.minX)return;
 const svg=chart.el.querySelector('svg.apexcharts-svg');if(!svg)return;
 svg.querySelector('.dashboard-day-labels')?.remove();
 const ns='http://www.w3.org/2000/svg';
 const group=document.createElementNS(ns,'g');group.setAttribute('class','dashboard-day-labels');group.setAttribute('pointer-events','none');group.setAttribute('transform',`translate(${g.translateX},${g.translateY})`);
 const fmt=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit'});
 const today=fmt.format(new Date());
 const parts=t=>Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(t).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
 const midnight=(t,offset=0)=>{const p=parts(t);const desired=Date.UTC(p.year,p.month-1,p.day+offset);let guess=desired;for(let i=0;i<3;i++){const q=parts(guess);guess+=desired-Date.UTC(q.year,q.month-1,q.day,q.hour,q.minute,q.second);}return guess;};
 const tomorrow=fmt.format(midnight(Date.now(),1));
 const x=t=>(t-g.minX)/(g.maxX-g.minX)*g.gridWidth;
 const node=(tag,attrs)=>{const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));group.appendChild(n);return n;};
 for(let start=midnight(g.minX),count=0;start<g.maxX&&count<4;count++){
  const end=midnight(start,1),day=fmt.format(start),label=day===today?'Idag':day===tomorrow?'Imorgon':day;
  if(start>g.minX&&start<g.maxX)node('line',{x1:x(start),x2:x(start),y1:0,y2:g.gridHeight,stroke:'#bdcbd5','stroke-opacity':'.4','stroke-width':1,'stroke-dasharray':'3 4'});
  const cx=(x(Math.max(start,g.minX))+x(Math.min(end,g.maxX)))/2;
